from pathlib import Path
from receipts import issue,reuse
import json
base='{"kind":"start","run_id":"r","expected":["a"]}\n{"kind":"result","run_id":"r","id":"a","status":"pass"}\n{"kind":"done","run_id":"r","ok":true}'
rows=[]
for name,raw in [('valid',base),('failure overwritten',base.replace('"status":"pass"','"status":"fail","status":"pass"')),('unsuccessful terminal overwritten',base.replace('"ok":true','"ok":false,"ok":true')),('plain failure',base.replace('"status":"pass"','"status":"fail"'))]:
 p=Path('report.jsonl');p.write_text(raw)
 try:r=issue(p,0,snapshot='exact-source');rows.append({'variant':name,'issued':r['status'],'reused':reuse(r,p,snapshot='exact-source'),'raw':raw})
 except ValueError:rows.append({'variant':name,'issued':False})
print(json.dumps(rows))
